package diplomacy.client;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.Texture;
import com.badlogic.gdx.graphics.g2d.SpriteBatch;
import com.badlogic.gdx.graphics.glutils.ShaderProgram;
import com.badlogic.gdx.utils.Disposable;
import java.util.IdentityHashMap;
import java.util.Map;

/**
 * Actual three-sampler GL2/ES2 hull shader. Preserves authored RGBA sprites.
 * Source-derived normal and emissive maps are generated by the ASSET BUILD,
 * uploaded once per unique source texture and never allocated in battle loops.
 */
final class ShipSurfaceLighting implements Disposable {
    static final String VERTEX =
        "attribute vec4 a_position;\n"+
        "attribute vec4 a_color;\n"+
        "attribute vec2 a_texCoord0;\n"+
        "uniform mat4 u_projTrans;\n"+
        "varying vec4 v_color;\n"+
        "varying vec2 v_uv;\n"+
        "void main(){v_color=a_color;v_uv=a_texCoord0;gl_Position=u_projTrans*a_position;}\n";
    static final String FRAGMENT =
        "#ifdef GL_ES\nprecision mediump float;\n#endif\n"+
        "varying vec4 v_color;\n"+
        "varying vec2 v_uv;\n"+
        "uniform sampler2D u_texture;\n"+
        "uniform sampler2D u_normal;\n"+
        "uniform sampler2D u_emission;\n"+
        "void main(){\n"+
        " vec4 albedo=texture2D(u_texture,v_uv);\n"+
        " albedo.a*=v_color.a;\n"+
        " if(albedo.a<0.004){gl_FragColor=vec4(0.0);return;}\n"+
        " vec3 n=normalize(texture2D(u_normal,v_uv).rgb*2.0-1.0);\n"+
        " vec2 axis=normalize(v_color.rg*2.0-1.0);\n"+
        " vec3 key=normalize(vec3(-0.52*axis.x+0.45*axis.y,\n"+
        "                          0.52*axis.y+0.45*axis.x,0.75));\n"+
        " float diffuse=max(dot(n,key),0.0);\n"+
        " float glint=pow(max(dot(reflect(-key,n),vec3(0.0,0.0,1.0)),0.0),24.0);\n"+
        " float rim=pow(clamp(1.0-n.z,0.0,1.0),2.0);\n"+
        " vec3 emitted=texture2D(u_emission,v_uv).rgb;\n"+
        " vec3 lit=albedo.rgb*(0.67+0.40*diffuse)+vec3(0.19)*glint;\n"+
        " lit+=vec3(0.055,0.10,0.13)*rim+emitted*0.95;\n"+
        " gl_FragColor=vec4(min(lit,vec3(1.0)),albedo.a);\n"+
        "}\n";

    private static final class Pair {
        final Texture normal,emissive;
        Pair(Texture normal,Texture emissive){this.normal=normal;this.emissive=emissive;}
        void dispose(){normal.dispose();emissive.dispose();}
    }
    private final Map<Texture,Pair> pairs=new IdentityHashMap<>();
    private final ShaderProgram shader;
    private Texture active;
    private boolean started;
    private int binds;

    ShipSurfaceLighting(){
        ShaderProgram.pedantic=false;
        ShaderProgram compiled=new ShaderProgram(VERTEX,FRAGMENT);
        if(!compiled.isCompiled()){
            String diagnostic=compiled.getLog();
            compiled.dispose();
            throw new IllegalStateException("Ship normal/emissive GL2 shader could not compile: "+diagnostic);
        }
        shader=compiled;
    }
    static String normalPath(String path){return surfacePath(path,"_n.png");}
    static String emissivePath(String path){return surfacePath(path,"_e.png");}
    private static String surfacePath(String path,String suffix){
        if(path==null||!path.startsWith("ships/")||!path.endsWith(".png"))
            throw new IllegalArgumentException("Invalid approved ship material path: "+path);
        return path.substring(0,path.length()-4)+suffix;
    }
    void prepare(Texture original,String path){
        if(pairs.containsKey(original))return;
        String n=normalPath(path),e=emissivePath(path);
        if(!Gdx.files.internal(n).exists()||!Gdx.files.internal(e).exists())
            throw new IllegalStateException("Required authored-source material maps missing: "+n+" / "+e);
        Texture normal=new Texture(Gdx.files.internal(n));
        Texture emissive=null;
        try {
            emissive=new Texture(Gdx.files.internal(e));
            if(normal.getWidth()!=emissive.getWidth()
                    ||normal.getHeight()!=emissive.getHeight()
                    ||normal.getWidth()>original.getWidth() || normal.getHeight()>original.getHeight()
                    ||Math.abs(normal.getWidth()/(float)original.getWidth()
                             -normal.getHeight()/(float)original.getHeight())>.015f)
                throw new IllegalStateException("Ship normal/emissive UV dimensions differ: "+path);
            normal.setFilter(Texture.TextureFilter.Linear,Texture.TextureFilter.Linear);
            emissive.setFilter(Texture.TextureFilter.Linear,Texture.TextureFilter.Linear);
            pairs.put(original,new Pair(normal,emissive));
        }catch(RuntimeException failure){
            normal.dispose();if(emissive!=null)emissive.dispose();
            throw failure;
        }
    }
    /**
     * Encode per-sprite rotation in the existing packed vertex color channels.
     * The material shader decodes it as world-light direction, not a tint.
     * No per-vessel uniform upload, shader rebind, or forced draw-call flush.
     */
    static void heading(SpriteBatch batch,float spriteRotationDegrees){
        double theta=Math.toRadians(spriteRotationDegrees);
        batch.setColor((float)(.5+.5*Math.cos(theta)),
                       (float)(.5+.5*Math.sin(theta)),1f,1f);
    }
    void begin(SpriteBatch batch){
        active=null;binds=0;started=true;
        batch.setShader(shader);
        batch.begin();
        shader.setUniformi("u_normal",1);
        shader.setUniformi("u_emission",2);
    }
    /** In the hot draw loop: only flush when the *source sprite* changes. */
    void bind(SpriteBatch batch,Texture original){
        Pair pair=pairs.get(original);
        if(pair==null)throw new IllegalStateException("Unprepared ship surface texture");
        if(batch.getShader()!=shader){
            batch.setShader(shader);
            shader.setUniformi("u_normal",1);
            shader.setUniformi("u_emission",2);
            active=null;
        }
        if(active==original)return;
        batch.flush();
        pair.normal.bind(1);
        pair.emissive.bind(2);
        Gdx.gl.glActiveTexture(GL20.GL_TEXTURE0);
        active=original;
        binds++;
    }
    /** Only truly unillustrated fallback craft should use the unlit path. */
    void unlit(SpriteBatch batch){
        if(batch.getShader()!=null)batch.setShader(null);
        active=null;
    }
    void end(SpriteBatch batch){
        if(!started)return;
        batch.end();
        batch.setShader(null);
        active=null;started=false;
    }
    int materialCount(){return pairs.size();}
    int textureBindings(){return binds;}
    @Override public void dispose(){
        for(Pair p:pairs.values())p.dispose();
        pairs.clear();
        shader.dispose();
    }
}
